/**
 *
 * The useRatingOption manages state and interactions for a single rating option (star).
 *
 * [Live Demo](https://www.primereact.org/rating/)
 *
 * @module useRatingOption
 * @group headless
 *
 */
import type { HeadlessInstance } from '@primereact/types/core';
import type { UseRatingInstance } from './useRating.types';
/**
 * Defines valid properties in useRatingOption.
 */
export interface UseRatingOptionProps {
    /**
     * The zero-based index of this option within the rating.
     */
    index: number;
    /**
     * The parent useRating instance providing state and methods.
     */
    context?: UseRatingInstance | undefined | null;
}
/**
 * Defines valid state in useRatingOption.
 */
export interface UseRatingOptionState {
    /**
     * Whether this option is highlighted (fully or partially filled).
     */
    highlighted: boolean;
    /**
     * Whether this option is half-filled.
     */
    half: boolean;
    /**
     * Whether this option is the checked/active one.
     */
    checked: boolean;
    /**
     * The active value (hovering value or committed value).
     */
    activeValue: number;
}
/**
 * Defines the methods and properties exposed by useRatingOption.
 */
export interface UseRatingOptionExposes {
    /**
     * Current state of this option.
     */
    state: UseRatingOptionState;
    /**
     * Ref to the option's root DOM element, used internally for pointer position calculations.
     */
    optionRef: React.RefObject<Element | null>;
    /**
     * Pre-built data attribute props for the option element.
     */
    optionProps: Record<string, string | number>;
    /**
     * Pre-built interaction props for the on-icon element.
     */
    onIconProps: {
        onMouseDown: (e: React.MouseEvent) => void;
        onPointerMove: (e: React.PointerEvent) => void;
        onClick: (e: React.MouseEvent) => void;
    };
    /**
     * Pre-built interaction props for the off-icon element.
     */
    offIconProps: {
        onMouseDown: (e: React.MouseEvent) => void;
        onPointerMove: (e: React.PointerEvent) => void;
        onClick: (e: React.MouseEvent) => void;
    };
    /**
     * Handle pointer move on On/Off elements (resolves half/full value and sets hovering value).
     */
    onPointerMove: (e: React.PointerEvent) => void;
    /**
     * Handle click on On/Off elements (resolves half/full value and updates value).
     */
    onClick: (e: React.MouseEvent) => void;
    /**
     * Prevent default on mouse down (avoids focus shift).
     */
    onMouseDown: (e: React.MouseEvent) => void;
    /**
     * Pre-built props for the half-value sr-only radio input. Null when allowHalf is false.
     */
    halfInputProps: React.InputHTMLAttributes<HTMLInputElement> | null;
    /**
     * Pre-built props for the full-value sr-only radio input.
     */
    fullInputProps: React.InputHTMLAttributes<HTMLInputElement>;
}
/**
 * Instance of useRatingOption headless.
 */
export type UseRatingOptionInstance = HeadlessInstance<UseRatingOptionProps, UseRatingOptionState, UseRatingOptionExposes>;
